#!/usr/bin/env python3
# -----------------------------------------------------------------------------
# gen_cxl_bridge.py -- generate the CXL port-adapter pin manifest and a
# lint-clean DPI-bridge stub (M6.1).
#
#   The width table is the frozen contract from the customer swdn boundary
#   document (CTL
#   constants).  The generated files are:
#     model/cxl_swdn_pins_gen.h        pin name / width / direction / mode
#     rtl_port/cxl_swdn_port_widths.svh width `defines for the RTL wrapper
#     rtl_port/cxl_swdn_dpi_stub.sv    DPI stub (active only with CXL_DPI_ENABLE)
#
#   The real DPI bridge is completed in the customer environment (M6.2):
#   the stub exposes the exact pin set and the C++ side consumes the manifest.
# -----------------------------------------------------------------------------
import os
import sys

# Frozen interface table (customer swdn boundary / CTL constants).
CXL_CHANNELS = [
    # name,               68B, 256B, PBR, dir(model view)
    ("H2D_REQ",           64,   72,   92, "tx"),
    ("H2D_RESP",          32,   40,   48, "tx"),
    ("H2D_DATA",         536,  540,  548, "tx"),
    ("D2H_REQ",           79,   76,   96, "rx"),
    ("D2H_RESP",          20,   24,   36, "rx"),
    ("D2H_DATA",         593,  600,  612, "rx"),
    ("M2S_REQ",           87,  100,  120, "tx"),
    ("M2S_RWD",          663,  680,  700, "tx"),
    ("S2M_NDR",           30,   40,   48, "rx"),
    ("S2M_DRC",          552,  552,  560, "rx"),
]

FIXED_PINS = [
    ("SRC0_PAYLOAD", 771, "tx_io"),
    ("SRC1_PAYLOAD", 771, "tx_io"),
    ("SRC2_PAYLOAD", 771, "tx_io"),
    ("SRC3_PAYLOAD", 771, "tx_io"),
    ("SRC4_PAYLOAD", 771, "tx_io"),
    ("RADM_PAYLOAD", 771, "rx_io"),
    ("DBI_DST_PAYLOAD", 37, "rx_dbi"),
    ("ELBI_ADDR", 32, "tx_elbi"),
    ("ELBI_DATA", 64, "tx_elbi"),
    ("EXT_LBC_DIN", 64, "rx_elbi"),
]


def emit_header(path):
    lines = []
    lines.append("// AUTO-GENERATED by tools/gen_cxl_bridge.py -- do not edit.")
    lines.append("#pragma once")
    lines.append("")
    lines.append("namespace cxl_tlm {")
    lines.append("")
    lines.append("struct CxlPin { const char* name; int w68; int w256; int wpbr; int dir; };")
    lines.append("// dir: 0=tx (model->swdn), 1=rx (swdn->model), 2=cxl.io tx, 3=cxl.io rx,")
    lines.append("//      4=DBI rx, 5=ELBI tx, 6=ELBI rx")
    lines.append("static const CxlPin kCxlPins[] = {")
    for name, w68, w256, wpbr, d in CXL_CHANNELS:
        dirv = 0 if d == "tx" else 1
        lines.append('    {"%s", %d, %d, %d, %d},' % (name, w68, w256, wpbr, dirv))
    dirmap = {"tx_io": 2, "rx_io": 3, "rx_dbi": 4, "tx_elbi": 5, "rx_elbi": 6}
    for name, w, d in FIXED_PINS:
        lines.append('    {"%s", %d, %d, %d, %d},' % (name, w, w, w, dirmap[d]))
    lines.append("};")
    lines.append("static const int kCxlPinCount = %d;" % (len(CXL_CHANNELS) + len(FIXED_PINS)))
    lines.append("")
    lines.append("} // namespace cxl_tlm")
    with open(path, "w") as f:
        f.write("\n".join(lines) + "\n")


def emit_widths(path):
    lines = ["// AUTO-GENERATED by tools/gen_cxl_bridge.py -- do not edit."]
    for name, w68, w256, wpbr, _ in CXL_CHANNELS:
        lines.append("`define CXL_W_%s_68B %d" % (name, w68))
        lines.append("`define CXL_W_%s_256B %d" % (name, w256))
        lines.append("`define CXL_W_%s_PBR %d" % (name, wpbr))
    for name, w, _d in FIXED_PINS:
        lines.append("`define CXL_W_%s %d" % (name, w))
    with open(path, "w") as f:
        f.write("\n".join(lines) + "\n")


def emit_stub(path):
    lines = [
        "// AUTO-GENERATED by tools/gen_cxl_bridge.py -- do not edit.",
        "// DPI bridge stub.  Active only when CXL_DPI_ENABLE is defined; the",
        "// default build is a lint-clean empty module (the real bridge is",
        "// completed with the customer swdn in M6.2).",
        "module cxl_swdn_dpi_stub;",
        "`ifdef CXL_DPI_ENABLE",
        '  import "DPI-C" context function void cxl_dpi_step(input int port);',
        '  import "DPI-C" context function void cxl_dpi_push_mem(input int port, input int chan);',
        '  export "DPI-C" function cxl_dpi_pull_credit;',
        "  function void cxl_dpi_pull_credit(input int port, input int chan);",
        "  endfunction",
        "`endif",
        "endmodule",
    ]
    with open(path, "w") as f:
        f.write("\n".join(lines) + "\n")


def main():
    root = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
    emit_header(os.path.join(root, "model", "cxl_swdn_pins_gen.h"))
    emit_widths(os.path.join(root, "rtl_port", "cxl_swdn_port_widths.svh"))
    emit_stub(os.path.join(root, "rtl_port", "cxl_swdn_dpi_stub.sv"))
    print("[gen-cxl-bridge] wrote model/cxl_swdn_pins_gen.h, "
          "rtl_port/cxl_swdn_port_widths.svh, rtl_port/cxl_swdn_dpi_stub.sv")
    return 0


if __name__ == "__main__":
    sys.exit(main())
